package kr.gyuhwan;
import com.fasterxml.jackson.databind.*;import java.util.*;import org.springframework.stereotype.Component;
// 가격 정책 JSON의 허용 모델·통신사·가입 조건·금액 범위를 한곳에서 검증한다.
// UI 저장, 엑셀 가져오기, 초기 설정 시드가 같은 규칙을 사용한다.
@Component public class QuoteValidator{
 private final Set<Integer> ids=new HashSet<>();public static final Set<String> AMOUNTS=Set.of("retail","common","support","installmentFee","planFee","discountBase","addonFee","addonMonths");private static final Set<String> TEXT=Set.of("planName","planDetails","addonDetails","penaltyDetails","terms");
 public QuoteValidator(ObjectMapper m)throws Exception{for(JsonNode p:m.readTree(getClass().getResourceAsStream("/products.json")))ids.add(p.path("id").asInt());}
 private void need(boolean b,String message){if(!b)throw new IllegalArgumentException(message);}
 // offers 키는 모델ID|통신사|가입유형|할인유형이다. 낯선 필드와 과도한 항목 수를 거부한다.
 public JsonNode validate(JsonNode c){need(c!=null&&c.isObject()&&c.path("offers").isObject()&&c.path("colors").isObject(),"설정 형식을 확인해 주세요.");c.fieldNames().forEachRemaining(n->need(Set.of("offers","colors","colorImages").contains(n),"알 수 없는 설정 항목"));need(c.path("offers").size()<=1000,"설정 개수 초과");
  c.path("offers").fields().forEachRemaining(e->{String[] k=e.getKey().split("\\|",-1);need(k.length==4,"견적 키 오류");int id;try{id=Integer.parseInt(k[0]);}catch(Exception x){throw new IllegalArgumentException("모델 번호 오류");}need(ids.contains(id)&&Set.of("SKT","KT","LG U+").contains(k[1])&&Set.of("번호이동","기기변경","신규가입").contains(k[2])&&Set.of("common","choice").contains(k[3]),"견적 조건 오류");JsonNode o=e.getValue();need(o.isObject(),"견적 항목 오류");o.fields().forEachRemaining(f->{JsonNode v=f.getValue();String n=f.getKey();if(AMOUNTS.contains(n)){need(v.isNull()||(v.isIntegralNumber()&&v.canConvertToLong()&&v.asLong()>=-100000000&&v.asLong()<=100000000&&(n.equals("support")||v.asLong()>=0)),"금액은 범위 내 원 단위 정수만 입력하세요.");}else if(TEXT.contains(n)){need(v.isTextual()&&v.asText().length()<=6000,"안내문 길이 오류");}else if(n.equals("supportInquiry")){need(v.isBoolean()&&(!v.asBoolean()||o.path("support").isIntegralNumber()&&o.path("support").asLong()==0),"문의 지원금은 0원으로 저장하세요.");}else if(n.equals("addonSchedule")){need(v.isArray()&&v.size()==24,"부가서비스 월별 금액 오류");for(JsonNode a:v)need(a.isIntegralNumber()&&a.canConvertToLong()&&a.asLong()>=0&&a.asLong()<=100000000,"부가서비스 월별 금액 오류");}else throw new IllegalArgumentException("알 수 없는 입력 항목");});
  // 선택약정과 공통지원금을 동시에 적용하지 않으며 할인 기준 금액은 25% 계산이 정확하도록 제한한다.
  if(k[3].equals("choice")){need(o.path("common").isMissingNode()||o.path("common").isNull()||o.path("common").asLong()==0,"선택약정 공통지원금 중복 오류");if(o.path("discountBase").isIntegralNumber()){need(o.path("discountBase").asLong()%4==0,"선택약정 할인 대상 금액은 4의 배수여야 합니다.");if(o.path("planFee").isIntegralNumber())need(o.path("discountBase").asLong()<=o.path("planFee").asLong(),"선택약정 할인 대상 금액이 월정액을 초과합니다.");}}
  if(o.path("addonMonths").isIntegralNumber())need(o.path("addonMonths").asLong()<=24,"부가서비스 기간은 0~24개월입니다.");if(o.path("addonFee").asLong()>0&&o.path("addonMonths").isIntegralNumber())need(o.path("addonMonths").asLong()>0,"유료 부가서비스 기간을 입력하세요.");
  });
  c.path("colors").fields().forEachRemaining(e->{need(ids.contains(Integer.parseInt(e.getKey()))&&e.getValue().isArray()&&e.getValue().size()<=30,"색상 모델 오류");Set<String> names=new HashSet<>();for(JsonNode n:e.getValue())need(n.isTextual()&&!n.asText().isBlank()&&n.asText().length()<=60&&names.add(n.asText()),"색상 정보 오류");});
  JsonNode images=c.path("colorImages");if(!images.isMissingNode()){need(images.isObject(),"색상 이미지 형식 오류");long[] total={0};images.fields().forEachRemaining(e->{need(ids.contains(Integer.parseInt(e.getKey()))&&e.getValue().isObject()&&e.getValue().size()<=30,"색상 이미지 모델 오류");e.getValue().fields().forEachRemaining(f->{String s=f.getValue().asText();need(f.getValue().isTextual()&&!f.getKey().isBlank()&&f.getKey().length()<=60&&s.length()<=40000&&s.matches("data:image/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}"),"색상 이미지 오류");total[0]+=s.length();});});need(total[0]<=600000,"색상 이미지 저장 용량 초과");}return c;
 }
}
